CREATE TABLE restaurants(id text PRIMARY KEY,name text NOT NULL,timezone text NOT NULL,menu_version integer NOT NULL DEFAULT 1,price_version integer NOT NULL DEFAULT 1,instructions text NOT NULL,upsell_enabled boolean NOT NULL DEFAULT false,pos_mode text NOT NULL DEFAULT 'accept' CHECK(pos_mode IN ('accept','reject','delay','unknown')));
CREATE TABLE products(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants(id),data jsonb NOT NULL);
CREATE TABLE lanes(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants(id),epoch integer NOT NULL DEFAULT 0,current_session uuid);
CREATE TABLE staff_users(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants(id),role text NOT NULL CHECK(role IN ('admin','crew','kitchen')),password_hash text NOT NULL,enabled boolean NOT NULL DEFAULT true);
CREATE TABLE interactions(id uuid PRIMARY KEY,lane_id text NOT NULL REFERENCES lanes(id),restaurant_id text NOT NULL REFERENCES restaurants(id),epoch integer NOT NULL,fence integer NOT NULL DEFAULT 0,owner text NOT NULL DEFAULT 'ai' CHECK(owner IN ('ai','staff')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','ended')),token_hash text NOT NULL,needs_staff_review boolean NOT NULL DEFAULT false,staff_message text,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE carts(session_id uuid PRIMARY KEY REFERENCES interactions(id),version integer NOT NULL DEFAULT 0,lines jsonb NOT NULL DEFAULT '[]',issues jsonb NOT NULL DEFAULT '[]');
CREATE TABLE quotes(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES interactions(id),snapshot jsonb NOT NULL,payload_hash text NOT NULL,fence integer NOT NULL,valid boolean NOT NULL DEFAULT true,expires_at timestamptz NOT NULL);
CREATE INDEX quotes_session ON quotes(session_id);
CREATE TABLE approvals(quote_id uuid PRIMARY KEY REFERENCES quotes(id),session_id uuid NOT NULL REFERENCES interactions(id),created_at timestamptz NOT NULL DEFAULT now(),consumed_at timestamptz);
CREATE TABLE orders(id uuid PRIMARY KEY,number serial NOT NULL,session_id uuid NOT NULL UNIQUE REFERENCES interactions(id),restaurant_id text NOT NULL REFERENCES restaurants(id),quote_id uuid NOT NULL UNIQUE REFERENCES quotes(id),external_key text NOT NULL UNIQUE,payload_hash text NOT NULL,snapshot jsonb NOT NULL,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','unknown','accepted','rejected','preparing','ready','handed_off')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','leased','done')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid);
CREATE INDEX jobs_claim ON jobs(state,available_at,lease_until);
CREATE TABLE pos_receipts(external_key text PRIMARY KEY,payload_hash text NOT NULL,status text NOT NULL CHECK(status IN ('accepted','rejected')),visible_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pos_attempts(id serial PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),operation text NOT NULL,outcome text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE handoffs(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES interactions(id),reason text NOT NULL,concern text,resolved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(key text PRIMARY KEY,payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id serial PRIMARY KEY,session_id uuid,kind text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
